const t = $json;
const description = String(t.description ?? '');
return {
  json: {
    business_key: String(t.ticket_id),
    ticket_id: String(t.ticket_id),
    premise_id: String(t.premise_id ?? ''),
    meter_id: String(t.meter_id ?? ''),
    address: String(t.address ?? ''),
    lat: t.lat ?? null,
    lon: t.lon ?? null,
    reported_at: t.reported_at ?? null,
    channel: String(t.channel ?? ''),
    description: description.slice(0, 1500),     // what the model sees
    description_full: description.slice(0, 20000), // what the safety screen reads
  },
};

// Deterministic, runs before the model. Anything that sounds like a hazard or a
// medically dependent customer goes straight to a dispatcher. Reads the full description.
const PATTERNS = ["\\b(?:wires?|lines?|cables?|power ?lines?) (?:is |are )?down\\b","\\bdowned\\b","\\b(?:wires?|lines?|cables?) (?:(?:is|are) )?(?:lying |hanging )?(?:on|across|over) the (?:ground|road|street|yard|car|house|roof|sidewalk|pavement)\\b","\\blive wires?\\b","\\bspark(?:s|ing|ed)?\\b","\\barcing\\b","\\bfire\\b","\\bon fire\\b","\\bsmoke\\b","\\bsmoking\\b","\\bburning\\b","\\bexplo(?:sion|ded|de|ding)\\b","\\bgas (?:smell|leak)\\b","\\bsmell(?:s|ing)? (?:of )?gas\\b","\\bpoles? (?:is |are )?(?:down|broken|snapped|leaning)\\b","\\btree (?:is )?(?:on|against|across|through) (?:the )?(?:power ?)?lines?\\b","\\btransformer (?:blew|exploded|is on fire|is smoking|is sparking)\\b","\\bshock(?:ed)?\\b","\\belectrocut","\\binjur","\\bhurt\\b","\\btrapped\\b","\\blife support\\b","\\boxygen\\b","\\bventilator\\b","\\bdialysis\\b"].map((p) => new RegExp(p, 'i'));
const t = $('Normalize ticket').first().json;
const text = t.description_full ?? t.description ?? '';
const hits = PATTERNS.map((r) => text.match(r)?.[0]).filter(Boolean);
return {
  json: {
    ...t,
    hazard: hits.length > 0,
    hazard_terms: hits,
    handoff_reason: hits.length ? 'SAFETY: customer report mentions ' + hits.join(', ') : '',
  },
};

